"""Seating charts laid out as one line of text per row."""

from typing import List, Sequence

from rosterkit.models import Student


def _name_key(student: Student):
    return (student.last_name.casefold(), student.first_name.casefold())


# ---
def seating_rows(students: Sequence[Student], seats_per_row: int) -> List[str]:
    """Sort by last name and lay students out, e.g. 'Row 1: Dunmere, Piet | Halloway, Juno'."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_name_key)
    return _build_rows(ordered, seats_per_row)


def _build_rows(ordered: Sequence[Student], width: int) -> List[str]:
    rows = []
    # Step through the sorted students one row at a time.
    for start in range(0, len(ordered), width):
        names = [item.display_name for item in ordered[start:start + width]]
        rows.append(f"Row {len(rows) + 1}: " + " | ".join(names))
    return rows
